const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define the region: 0-40 degrees South, global longitude
  const region = ee.Geometry.Rectangle([-180, -40, 180, 0]);

  // Define the date
  const targetDate = '2025-02-26';
  const dateStart = ee.Date(targetDate);
  const dateEnd = dateStart.advance(1, 'day');

  console.log('Searching for tropical cyclone signatures on February 26, 2025');
  console.log('Region: 0-40 degrees South');

  // Try multiple data sources for cyclone detection

  // 1. Try MODIS Terra (visible/infrared for cloud patterns)
  let modis = ee.ImageCollection('MODIS/061/MOD021KM')
    .filterDate(dateStart, dateEnd)
    .filterBounds(region);

  const modisCount = modis.size().getInfo();
  console.log(`MODIS images found: ${modisCount}`);

  // 2. Try GPM IMERG precipitation (cyclones show as high precipitation)
  let imerg = ee.ImageCollection('NASA/GPM_L3/IMERG_V06')
    .filterDate(dateStart, dateEnd)
    .filterBounds(region);

  const imergCount = imerg.size().getInfo();
  console.log(`IMERG precipitation images found: ${imergCount}`);

  // 3. Try ERA5 wind data (cyclones have strong winds)
  let era5 = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .filterDate(dateStart, dateEnd)
    .filterBounds(region);

  const era5Count = era5.size().getInfo();
  console.log(`ERA5 images found: ${era5Count}`);

  // Check if any data source has images
  if (modisCount === 0 && imergCount === 0 && era5Count === 0) {
    console.log('No satellite data available for February 26, 2025');
    console.log('This date is in the future - data not yet collected');
    console.log('<answer>C1</answer>');
    return;
  }

  // If we have IMERG data, analyze precipitation patterns
  if (imergCount > 0) {
    const precipImage = imerg.select('precipitationCal').mean();

    // Get statistics on high precipitation areas
    const highPrecip = precipImage.gt(10); // > 10mm/hr indicates strong convection

    const stats = highPrecip.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: region,
      scale: 25000,
      maxPixels: 1e9
    });

    const pixelCount = stats.get('precipitationCal').getInfo();
    console.log(`High precipitation pixels: ${pixelCount}`);

    if (pixelCount === null || pixelCount === 0) {
      console.log('No valid precipitation data after processing');
      console.log('<answer>C2</answer>');
      return;
    }

    // Note: Without actual cyclone tracking database, we cannot definitively
    // count distinct tropical cyclones from satellite imagery alone
    console.log('Data exists but GEE does not have cyclone tracking database');
    console.log('Cannot verify distinct tropical cyclone count from imagery alone');
    console.log('<answer>D</answer>');
    return;
  }

  console.log('Unable to analyze cyclone patterns with available data');
  console.log('<answer>D</answer>');
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
